function insnUnits(op){
  if(op===0x00||(op>=0x0e&&op<=0x11)||op===0x12||op===0x1d||op===0x1e||op===0x21||op===0x27||op===0x28||(op>=0x7b&&op<=0x8f)||(op>=0xb0&&op<=0xcf)) return 1;
  if(op===0x18) return 5;
  if(op===0x03||op===0x06||op===0x09||op===0x14||op===0x17||op===0x1b||op===0x24||op===0x25||op===0x2a||op===0x2b||op===0x2c||(op>=0x6e&&op<=0x72)||(op>=0x74&&op<=0x78)) return 3;
  return 2;
}
function parseDex(raw, dexName){
  const stringIdsOff=raw.readUInt32LE(60), stringIdsSize=raw.readUInt32LE(56);
  const typeIdsOff=raw.readUInt32LE(68), typeIdsSize=raw.readUInt32LE(64);
  const protoIdsOff=raw.readUInt32LE(76);
  const fieldIdsOff=raw.readUInt32LE(84), fieldIdsSize=raw.readUInt32LE(80);
  const methodIdsOff=raw.readUInt32LE(92), methodIdsSize=raw.readUInt32LE(88);
  const classDefsOff=raw.readUInt32LE(100), classDefsSize=raw.readUInt32LE(96);
  const strings=new Array(stringIdsSize);
  for(let i=0;i<stringIdsSize;i++){ const off=raw.readUInt32LE(stringIdsOff+i*4); const [,p]=uleb(raw, off); strings[i]=mutf8(raw, p); }
  function typeName(idx){ return (idx>=0&&idx<typeIdsSize)?strings[raw.readUInt32LE(typeIdsOff+idx*4)]:'?'; }
  function protoName(idx){
    const retIdx=raw.readUInt32LE(protoIdsOff+idx*12+4);
    const paramsOff=raw.readUInt32LE(protoIdsOff+idx*12+8);
    let params='';
    if(paramsOff){ const size=raw.readUInt32LE(paramsOff); for(let i=0;i<size;i++) params += typeName(raw.readUInt16LE(paramsOff+4+i*2)); }
    return '('+params+')'+typeName(retIdx);
  }
  function methodName(idx){
    const classIdx=raw.readUInt16LE(methodIdsOff+idx*8);
    const protoIdx=raw.readUInt16LE(methodIdsOff+idx*8+2);
    const nameIdx=raw.readUInt32LE(methodIdsOff+idx*8+4);
    return typeName(classIdx)+'->'+strings[nameIdx]+protoName(protoIdx);
  }
  function fieldName(idx){
    const classIdx=raw.readUInt16LE(fieldIdsOff+idx*8);
    const typeIdx=raw.readUInt16LE(fieldIdsOff+idx*8+2);
    const nameIdx=raw.readUInt32LE(fieldIdsOff+idx*8+4);
    return typeName(classIdx)+'.'+strings[nameIdx]+':'+typeName(typeIdx);
  }
  const wantedStr = {};
  for(let i=0;i<strings.length;i++){
    if(/dock_max_num_statue|dock_max_num_status|"'^dock_max$|''^dock_num$|writeDockNumMaxStatue|getDockShowStatue/.test(strings[i])) wantedStr[i]=strings[i];
  }
  console.log('"'DEX', dexName, 'wanted strings', JSON.stringify(wantedStr));
  const wantedMethods = [];
  for(let i=0;i<methodIdsSize;i++){
    const nameIdx=raw.readUInt32LE(methodIdsOff+i*8+4);
    const s=strings[nameIdx];
    if(/writeDockNumMaxStatue|getDockShowStatue|writeSecure|getInt|putInt|getDockNum|getDockUserDefAppNum/.test(s)){
      const mn=methodName(i);
      if(/QuickNoteUtils|Utils;|DockModel|HispServices|Settings|Preference|DockViewModel/.test(mn) || /writeDockNumMaxStatue|getDockShowStatue/.test(s))
        wantedMethods.push([i,mn]);
    }
