  wantedMethods.slice(0,80).forEach(([i,n])=>console.log('M', i, n));

  function decodeCode(codeOff, owner){
    const registers=raw.readUInt16LE(codeOff);
    const insSize=raw.readUInt16LE(codeOff+2);
    const outs=raw.readUInt16LE(codeOff+4);
    const tries=raw.readUInt16LE(codeOff+6);
    const debugOff=raw.readUInt32LE(codeOff+8);
    const insnsSize=raw.readUInt32LE(codeOff+12);
    const insnsOff=codeOff+16;
    console.log('\\\\n==== CODE', owner, 'regs', registers, 'ins', insSize, 'outs', outs, 'tries', tries, 'insns', insnsSize, '====');
    let i=0;
    while(i<insnsSize){
      const op=raw[insnsOff+i*2];
      const units=insnUnits(op);
      const bytes=[];
      for(let k=0;k<units*2 && (i+Math.floor(k/2))<insnsSize;k++) bytes.push(raw[insnsOff+i*2+k].toString(16).padStart(2,'0'));
      const name=OP[op]||('op_'+op.toString(16));
      let extra='';
      const b1=raw[insnsOff+i*2+1];
      if(op===0x1a){ const sid=raw.readUInt16LE(insnsOff+i*2+2); extra=' v'+(b1)+' \\\"'+strings[sid]+'\\\"'; }
      else if(op===0x1b){ const sid=raw.readUInt32LE(insnsOff+i*2+2); extra=' v'+(b1)+' jumbo \\\"'+strings[sid]+'\\\"'; }
      else if(op===0x12){ extra=' v'+(b1&0x0f)+' #'+(((b1>>4)<<28)>>28); }
      else if(op===0x13){ extra=' v'+b1+' #'+raw.readInt16LE(insnsOff+i*2+2); }
