      else if(op>=0x74 && op<=0x78){ const count=b1; const meth=raw.readUInt16LE(insnsOff+i*2+2); const first=raw.readUInt16LE(insnsOff+i*2+4); extra=' count='+count+' first=v'+first+' '+methodName(meth); }
      else if(op>=0x52 && op<=0x6d){ const field=raw.readUInt16LE(insnsOff+i*2+2); extra=' v'+(b1&0x0f)+', v'+(b1>>4)+' '+fieldName(field); }
      else if(op===0x22||op===0x1c||op===0x1f){ extra=' v'+b1+' '+typeName(raw.readUInt16LE(insnsOff+i*2+2)); }
      else if(op>=0x38 && op<=0x3d){ extra=' v'+b1+' +'+raw.readInt16LE(insnsOff+i*2+2); }
      else if(op>=0x32 && op<=0x37){ extra=' v'+(b1&0x0f)+', v'+(b1>>4)+' +'+raw.readInt16LE(insnsOff+i*2+2); }
      else if(op===0x0e) extra='';
      else extra=' '+bytes.join(' ');
      console.log(('000'+i.toString(16)).slice(-4)+': '+name+extra);
      i += units;
      if(units<=0) break;
    }
  }

  // find class defs for QuickNoteUtils and callers by scanning all class_data encoded methods
  const targetClassNames = new Set([
    'Lcom/hihonor/hndockbar/utils/QuickNoteUtils;',
    'Lcom/hihonor/hndockbar/hispservices/HispServicesManager;',
    'Lcom/hihonor/hndockbar/dock/DockViewModel;',
