  const wantedMethodNameSet = new Set(['writeDockNumMaxStatue','writeSecure','getDockShowStatue','getDockNum','getDockUserDefAppNum','writeDockData']);
  const stringUseSites = [];
  for(let c=0;c<classDefsSize;c++){
    const classIdx=raw.readUInt32LE(classDefsOff+c*32);
    const classDataOff=raw.readUInt32LE(classDefsOff+c*32+24);
    const cls=typeName(classIdx);
