    let p=classDataOff;
    let nStaticF,nInstF,nDirect,nVirtual;
    [nStaticF,p]=uleb(raw,p); [nInstF,p]=uleb(raw,p); [nDirect,p]=uleb(raw,p); [nVirtual,p]=uleb(raw,p);
    function skipFields(n){ let idx=0; for(let i=0;i<n;i++){ let d; [d,p]=uleb(raw,p); idx+=d; [,p]=uleb(raw,p);} }
