    function walkMethods(n, kind){
      let idx=0;
      for(let i=0;i<n;i++){
        let d, access, codeOff;
        [d,p]=uleb(raw,p); idx+=d; [access,p]=uleb(raw,p); [codeOff,p]=uleb(raw,p);
        const mname = methodName(idx);
        const simple = strings[raw.readUInt32LE(methodIdsOff+idx*8+4)];
        if(codeOff){
          // scan insns for const-string of wanted strings and invoke of writeDockNumMaxStatue
          const insnsSize=raw.readUInt32LE(codeOff+12);
          const insnsOff=codeOff+16;
          let ip=0;
          while(ip<insnsSize){
            const op=raw[insnsOff+ip*2];
            const units=insnUnits(op);
            if(op===0x1a){ const sid=raw.readUInt16LE(insnsOff+ip*2+2); if(wantedStr[sid]) stringUseSites.push({cls, simple, mname, sid, str:wantedStr[sid], ip, codeOff}); }
            if(op===0x1b){ const sid=raw.readUInt32LE(insnsOff+ip*2+2); if(wantedStr[sid]) stringUseSites.push({cls, simple, mname, sid, str:wantedStr[sid], ip, codeOff}); }
            if(op>=0x6e && op<=0x72){ const meth=raw.readUInt16LE(insnsOff+ip*2+2); const called=methodName(meth); if(/writeDockNumMaxStatue|getDockShowStatue/.test(called)) stringUseSites.push({cls, simple, mname, invoke:called, ip, codeOff}); }
            if(op>=0x74 && op<=0x78){ const meth=raw.readUInt16LE(insnsOff+ip*2+2); const called=methodName(meth); if(/writeDockNumMaxStatue|getDockShowStatue/.test(called)) stringUseSites.push({cls, simple, mname, invoke:called, ip, codeOff}); }
            ip += units; if(units<=0) break;
          }
        }
        if(wantedMethodNameSet.has(simple) && (targetClassNames.has(cls) || /writeDockNumMaxStatue|getDockShowStatue/.test(simple))){
          if(codeOff) decodeCode(codeOff, mname);
          else console.log('"'NO CODE', mname);
        }
      }
    }
    walkMethods(nDirect,'d');
    walkMethods(nVirtual,'v');
  }
  console.log('\\\\n==== STRING/INVOKE USE SITES', stringUseSites.length, '====');
  stringUseSites.forEach(s=>console.log(JSON.stringify(s)));
}

